// DimDate — generated by src/powerbi/build_assets.py from DimDate.csv
// Grain/keys: see powerbi/data_model.md
let
    Source   = Csv.Document(File.Contents(DataFolder & "DimDate.csv"),
                            [Delimiter = ",", Encoding = 65001, QuoteStyle = QuoteStyle.Csv]),
    Promoted = Table.PromoteHeaders(Source, [PromoteAllScalars = true]),
    Typed    = Table.TransformColumnTypes(Promoted, {
        {"Date", type date},
        {"year", Int64.Type},
        {"quarter", Int64.Type},
        {"month", Int64.Type},
        {"month_name", type text},
        {"week", Int64.Type},
        {"day", Int64.Type},
        {"day_name", type text},
        {"weekday_flag", Int64.Type},
        {"year_month", type text},
        {"quarter_label", type text},
        {"DateKey", Int64.Type},
        {"MonthStart", type date},
        {"IsWeekend", Int64.Type}
    }, "en-US")
in
    Typed
